<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Terms Consent Form</title>
    <style>
      :root {
        color-scheme: light;
        --color-page: #f7f9fc;
        --color-surface: #ffffff;
        --color-surface-muted: #f1f5f9;
        --color-text: #111827;
        --color-muted: #4b5563;
        --color-primary: #155eef;
        --color-primary-hover: #0f48c4;
        --color-border: #cbd5e1;
        --color-focus: #ffbf47;
        --shadow-card: 0 24px 70px #d4deea;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        min-width: 320px;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
        color: var(--color-text);
        background:
          radial-gradient(circle at top left, #dbeafe 0, transparent 34rem),
          linear-gradient(135deg, var(--color-page), #eef2ff);
      }

      a {
        color: var(--color-primary);
        font-weight: 700;
        text-decoration-thickness: 0.12em;
        text-underline-offset: 0.16em;
      }

      a:hover {
        color: var(--color-primary-hover);
      }

      a:focus-visible,
      button:focus-visible,
      input:focus-visible {
        outline: 3px solid var(--color-focus);
        outline-offset: 3px;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        color: var(--color-text);
        background: var(--color-surface);
        border: 2px solid var(--color-text);
        border-radius: 999px;
        transform: translateY(-140%);
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        display: grid;
        min-height: 100vh;
        padding: clamp(1rem, 4vw, 3rem);
        place-items: center;
      }

      .consent-card {
        width: min(100%, 34rem);
        padding: clamp(1.5rem, 5vw, 2.75rem);
        background: var(--color-surface);
        border: 1px solid var(--color-border);
        border-radius: 1.5rem;
        box-shadow: var(--shadow-card);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--color-primary);
        font-size: 0.8125rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 8vw, 3.25rem);
        line-height: 1;
        letter-spacing: -0.05em;
      }

      .intro {
        margin: 1rem 0 2rem;
        color: var(--color-muted);
        font-size: 1rem;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.875rem;
        padding: 1rem;
        background: var(--color-surface-muted);
        border: 1px solid var(--color-border);
        border-radius: 1rem;
      }

      .form-field input[type="checkbox"] {
        width: 1.375rem;
        height: 1.375rem;
        margin: 0.12rem 0 0;
        accent-color: var(--color-primary);
      }

      .field-copy {
        min-width: 0;
      }

      .checkbox-label {
        display: inline;
        font-weight: 800;
      }

      .required-marker {
        margin-left: 0.15rem;
        color: #9f1239;
        font-weight: 900;
      }

      .helper-text {
        margin: 0.35rem 0 0;
        color: var(--color-muted);
        font-size: 0.9375rem;
      }

      .submit-button {
        width: 100%;
        min-height: 3rem;
        padding: 0.875rem 1.25rem;
        color: #ffffff;
        background: var(--color-primary);
        border: 2px solid var(--color-primary);
        border-radius: 999px;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        box-shadow: 0 10px 24px #b7c8f7;
      }

      .submit-button:hover {
        background: var(--color-primary-hover);
        border-color: var(--color-primary-hover);
      }

      .submit-button:active {
        transform: translateY(1px);
      }

      .status-message {
        min-height: 1.5rem;
        margin: 0;
        color: #166534;
        font-weight: 700;
      }

      @media (max-width: 23rem) {
        .consent-card {
          border-radius: 1rem;
        }

        .form-field {
          gap: 0.75rem;
          padding: 0.875rem;
        }
      }

      @media (forced-colors: active) {
        body,
        .consent-card,
        .form-field {
          color: CanvasText;
          background: Canvas;
          border-color: ButtonBorder;
          box-shadow: none;
        }

        .eyebrow,
        .intro,
        .helper-text,
        a,
        a:hover,
        .status-message {
          color: CanvasText;
        }

        .submit-button {
          color: ButtonText;
          background: ButtonFace;
          border-color: ButtonBorder;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <script type="text/babel">
      const { useState } = React;

      function ConsentCheckbox() {
        return (
          <div className="form-field">
            <input
              id="terms-consent"
              name="termsConsent"
              type="checkbox"
              required
              aria-describedby="terms-consent-help"
            />
            <div className="field-copy">
              <label className="checkbox-label" htmlFor="terms-consent">
                I agree to the terms of use
                <span className="required-marker" aria-hidden="true">
                  *
                </span>
              </label>
              <p className="helper-text" id="terms-consent-help">
                Required to create and manage your account.
              </p>
            </div>
          </div>
        );
      }

      function ConsentForm() {
        const [message, setMessage] = useState("");

        function handleSubmit(event) {
          event.preventDefault();

          if (!event.currentTarget.reportValidity()) {
            setMessage("");
            return;
          }

          setMessage("Thanks. Your consent has been recorded.");
          event.currentTarget.reset();
        }

        return (
          <form onSubmit={handleSubmit} noValidate={false}>
            <ConsentCheckbox />
            <button className="submit-button" type="submit">
              Submit agreement
            </button>
            <p className="status-message" aria-live="polite">
              {message}
            </p>
          </form>
        );
      }

      function App() {
        return (
          <main className="page-shell" id="main-content">
            <section className="consent-card" aria-labelledby="page-title">
              <p className="eyebrow">Terms consent</p>
              <h1 id="page-title">Review and agree</h1>
              <p className="intro">
                Confirm that you accept the terms before continuing.
              </p>
              <ConsentForm />
            </section>
          </main>
        );
      }

      ReactDOM.createRoot(document.getElementById("root")).render(<App />);
    </script>
  </body>
</html>
